def max_product(nums):
    if not nums:
        return None
    max_product = float('-inf')
    max_left = float('-inf')
    max_right = float('-inf')
    for num in nums:
        if num > max_left:
            max_right = max_left
            max_left = num
        elif num < max_left:
            if max_right < num * max_left:
                max_product = max_right
            max_right = num * max_left
            max_left = num
        elif num < max_right:
            max_right = num
    return max_product

